theorem niveauOneCarryInput_abs_le {p f : Nat}
    (sigma sigma' : PhantomWeight p f) (J J' : Set (ZMod f))
    (i : ZMod f) : |niveauOneCarryInput sigma sigma' J J' i| ≤ 2 * (p : Int)

theorem translationExponent_residueRepresentative {p f : Nat}
    (hp : 2 ≤ p) (hf : 2 ≤ f) (a : ZMod (p ^ f - 1)) :
    translationExponent p f hf (residueRepresentative a) = a

theorem carryEquation_existsUnique_of_translationExponent_eq_zero {p n : Nat}
    (hp : 2 ≤ p) (hn : 2 ≤ n) {y : ZMod n → Int}
    (hzero : translationExponent p n hn y = 0) :
    ∃! x : ZMod n → Int, CarryEquation p y x

theorem threePowerPlusOne_not_dvd_two_signedThreeWeightedSum {f : Nat}
    (hf : 2 ≤ f) (z : ZMod f → Int) (hz : ∀ i, z i = 3 ∨ z i = -3) :
    ¬ ((3 : Int) ^ f + 1) ∣ 2 * manuscriptCyclicWeightedSum 3 f z

theorem niveauOneScalarCarryInput_abs_le {p f : Nat}
    (sigma : PhantomWeight p f) (J : Set (ZMod f)) :
    ∀ i, |niveauOneScalarCarryInput sigma J i| ≤ (p : Int)

theorem translationExponent_eq_zero_of_carryEquation {p n : Nat}
    (hp : 2 ≤ p) (hn : 2 ≤ n) {y x : ZMod n → Int}
    (hx : CarryEquation p y x) :
    translationExponent p n hn y = 0

theorem shiftedNiveauTwoProfileHalfDifference_apply {p f : Nat}
    (hf : 2 ≤ f) (sigma : PhantomWeight p f) (J : Set (ZMod f))
    (a i : ZMod (2 * f)) :
    shiftedNiveauTwoProfileHalfDifference hf sigma J a i =
      if (i - a).val < f then 0
      else niveauOneScalarCarryInput sigma J (periodicIndex hf i)

theorem critical_niveauOneProfileSum_univ_eq_zero {p f : Nat}
    (hp : 3 ≤ p) (hf : 2 ≤ f) (t : ZMod (p ^ f - 1)) :
    niveauOneProfileSum hf (PhantomWeight.critical p f t) Set.univ = 0

theorem boundedHomogeneousPair_eq_zero {p : Nat} (hp : 3 ≤ p) {a b : Int}
    (ha : |a| ≤ 2) (hb : |b| ≤ 2) (hrecurrence : (p : Int) * a = b) :
    a = 0 ∧ b = 0

theorem periodicIndexSet_singleton {f : Nat} (hf : 2 ≤ f)
    (a : ZMod (2 * f)) :
    periodicIndexSet hf {periodicIndex hf a} = {a, a + f}

theorem simpleInclusionIn_of_covBy
    {p f : Nat} {I A : Type*} [Monoid I] [CommGroup A]
    {hp : 2 ≤ p} {hf : 2 ≤ f}
    {chars : FundamentalCharacterSystem p f I A}
    {X Y : SemisimpleSupportSet hp hf chars}
    (hCov : X ⋖ Y) :
    SimpleInclusionIn (semisimpleCharacterSetFamily hp hf chars) X.1 Y.1
